insert into public.scenarios (slug, language, title, theme, level_min, level_max, minutes, illustration_storage_path, subtitle, brief, tasks, pip_prompt, sort_order) values
  ('introduce', 'fr', 'Se présenter', 'social', 'A1', 'A2', 6, 'scenarios/introduce.webp', '{"de": "Kennenlernen", "en": "Getting to know", "es": "Conocerse", "fr": "Faire connaissance", "it": "Conoscersi", "pt": "Conhecer-se"}', '{"de": "Du triffst jemanden zum ersten Mal auf einer kleinen Feier. Stell dich vor und finde etwas über die andere Person heraus.", "en": "You meet someone for the first time at a small party. Introduce yourself and find out something about them.", "es": "Conoces a alguien por primera vez en una pequeña fiesta. Preséntate y averigua algo sobre esa persona.", "fr": "Tu rencontres quelqu’un pour la première fois à une petite fête. Présente-toi et apprends quelque chose sur cette personne.", "it": "Incontri qualcuno per la prima volta a una piccola festa. Presentati e scopri qualcosa su questa persona.", "pt": "Conheces alguém pela primeira vez numa pequena festa. Apresenta-te e descobre algo sobre essa pessoa."}', '[{"id": "greet", "level": "A1", "text": {"de": "Begrüße die Person und sag deinen Namen", "en": "Greet the person and say your name", "es": "Saluda a la persona y di tu nombre", "fr": "Salue la personne et dis ton nom", "it": "Saluta la persona e di’ il tuo nome", "pt": "Cumprimenta a pessoa e diz o teu nome"}, "hint": "Bonjour, je m’appelle …"}, {"id": "origin", "level": "A1", "text": {"de": "Sag, woher du kommst und wo du wohnst", "en": "Say where you are from and where you live", "es": "Di de dónde eres y dónde vives", "fr": "Dis d’où tu viens et où tu habites", "it": "Di’ da dove vieni e dove abiti", "pt": "Diz de onde és e onde moras"}, "hint": "Je viens de … / J’habite à …"}, {"id": "ask", "level": "A2", "text": {"de": "Frag die Person nach ihrem Beruf oder Hobby", "en": "Ask the person about their job or a hobby", "es": "Pregunta a la persona por su trabajo o una afición", "fr": "Demande à la personne son métier ou un loisir", "it": "Chiedi alla persona che lavoro fa o un hobby", "pt": "Pergunta à pessoa sobre o trabalho ou um passatempo"}, "hint": "Qu’est-ce que tu fais dans la vie ?"}]', 'Tu es un invité sympathique à une petite fête. Tu rencontres l’apprenant pour la première fois. Pose des questions simples, réponds brièvement et laisse-le parler.', 1),
  ('introduce', 'en', 'Introducing yourself', 'social', 'A1', 'A2', 6, 'scenarios/introduce.webp', '{"de": "Kennenlernen", "en": "Getting to know", "es": "Conocerse", "fr": "Faire connaissance", "it": "Conoscersi", "pt": "Conhecer-se"}', '{"de": "Du triffst jemanden zum ersten Mal auf einer kleinen Feier. Stell dich vor und finde etwas über die andere Person heraus.", "en": "You meet someone for the first time at a small party. Introduce yourself and find out something about them.", "es": "Conoces a alguien por primera vez en una pequeña fiesta. Preséntate y averigua algo sobre esa persona.", "fr": "Tu rencontres quelqu’un pour la première fois à une petite fête. Présente-toi et apprends quelque chose sur cette personne.", "it": "Incontri qualcuno per la prima volta a una piccola festa. Presentati e scopri qualcosa su questa persona.", "pt": "Conheces alguém pela primeira vez numa pequena festa. Apresenta-te e descobre algo sobre essa pessoa."}', '[{"id": "greet", "level": "A1", "text": {"de": "Begrüße die Person und sag deinen Namen", "en": "Greet the person and say your name", "es": "Saluda a la persona y di tu nombre", "fr": "Salue la personne et dis ton nom", "it": "Saluta la persona e di’ il tuo nome", "pt": "Cumprimenta a pessoa e diz o teu nome"}, "hint": "Hi, my name is …"}, {"id": "origin", "level": "A1", "text": {"de": "Sag, woher du kommst und wo du wohnst", "en": "Say where you are from and where you live", "es": "Di de dónde eres y dónde vives", "fr": "Dis d’où tu viens et où tu habites", "it": "Di’ da dove vieni e dove abiti", "pt": "Diz de onde és e onde moras"}, "hint": "I’m from … / I live in …"}, {"id": "ask", "level": "A2", "text": {"de": "Frag die Person nach ihrem Beruf oder Hobby", "en": "Ask the person about their job or a hobby", "es": "Pregunta a la persona por su trabajo o una afición", "fr": "Demande à la personne son métier ou un loisir", "it": "Chiedi alla persona che lavoro fa o un hobby", "pt": "Pergunta à pessoa sobre o trabalho ou um passatempo"}, "hint": "What do you do?"}]', 'You are a friendly guest at a small party meeting the learner for the first time. Ask simple questions, answer briefly and let them do most of the talking.', 1),
  ('introduce', 'es', 'Presentarse', 'social', 'A1', 'A2', 6, 'scenarios/introduce.webp', '{"de": "Kennenlernen", "en": "Getting to know", "es": "Conocerse", "fr": "Faire connaissance", "it": "Conoscersi", "pt": "Conhecer-se"}', '{"de": "Du triffst jemanden zum ersten Mal auf einer kleinen Feier. Stell dich vor und finde etwas über die andere Person heraus.", "en": "You meet someone for the first time at a small party. Introduce yourself and find out something about them.", "es": "Conoces a alguien por primera vez en una pequeña fiesta. Preséntate y averigua algo sobre esa persona.", "fr": "Tu rencontres quelqu’un pour la première fois à une petite fête. Présente-toi et apprends quelque chose sur cette personne.", "it": "Incontri qualcuno per la prima volta a una piccola festa. Presentati e scopri qualcosa su questa persona.", "pt": "Conheces alguém pela primeira vez numa pequena festa. Apresenta-te e descobre algo sobre essa pessoa."}', '[{"id": "greet", "level": "A1", "text": {"de": "Begrüße die Person und sag deinen Namen", "en": "Greet the person and say your name", "es": "Saluda a la persona y di tu nombre", "fr": "Salue la personne et dis ton nom", "it": "Saluta la persona e di’ il tuo nome", "pt": "Cumprimenta a pessoa e diz o teu nome"}, "hint": "Hola, me llamo …"}, {"id": "origin", "level": "A1", "text": {"de": "Sag, woher du kommst und wo du wohnst", "en": "Say where you are from and where you live", "es": "Di de dónde eres y dónde vives", "fr": "Dis d’où tu viens et où tu habites", "it": "Di’ da dove vieni e dove abiti", "pt": "Diz de onde és e onde moras"}, "hint": "Soy de … / Vivo en …"}, {"id": "ask", "level": "A2", "text": {"de": "Frag die Person nach ihrem Beruf oder Hobby", "en": "Ask the person about their job or a hobby", "es": "Pregunta a la persona por su trabajo o una afición", "fr": "Demande à la personne son métier ou un loisir", "it": "Chiedi alla persona che lavoro fa o un hobby", "pt": "Pergunta à pessoa sobre o trabalho ou um passatempo"}, "hint": "¿A qué te dedicas?"}]', 'Eres un invitado simpático en una pequeña fiesta y conoces al estudiante por primera vez. Haz preguntas sencillas, responde brevemente y deja que hable.', 1),
  ('directions', 'fr', 'Demander son chemin', 'travel', 'A1', 'B1', 5, 'scenarios/directions.webp', '{"de": "Weg finden", "en": "Finding your way", "es": "Orientarse", "fr": "Trouver son chemin", "it": "Orientarsi", "pt": "Encontrar o caminho"}', '{"de": "Du bist neu in der Stadt und suchst den Bahnhof. Sprich eine Passantin an und lass dir den Weg erklären.", "en": "You are new in town and looking for the station. Stop a passer-by and get directions.", "es": "Eres nuevo en la ciudad y buscas la estación. Para a una transeúnte y pide indicaciones.", "fr": "Tu es nouveau en ville et tu cherches la gare. Aborde une passante et fais-toi expliquer le chemin.", "it": "Sei nuovo in città e cerchi la stazione. Ferma una passante e fatti spiegare la strada.", "pt": "És novo na cidade e procuras a estação. Aborda uma transeunte e pede indicações."}', '[{"id": "ask", "level": "A1", "text": {"de": "Frag höflich nach dem Weg zum Bahnhof", "en": "Politely ask the way to the station", "es": "Pregunta amablemente cómo llegar a la estación", "fr": "Demande poliment le chemin de la gare", "it": "Chiedi gentilmente la strada per la stazione", "pt": "Pergunta com educação o caminho para a estação"}, "hint": "Excusez-moi, où est la gare ?"}, {"id": "repeat", "level": "A2", "text": {"de": "Bitte darum, es langsamer zu wiederholen", "en": "Ask them to repeat more slowly", "es": "Pide que lo repita más despacio", "fr": "Demande de répéter plus lentement", "it": "Chiedi di ripetere più lentamente", "pt": "Pede para repetir mais devagar"}, "hint": "Pourriez-vous répéter plus lentement ?"}, {"id": "confirm", "level": "B1", "text": {"de": "Fasse den Weg mit eigenen Worten zusammen", "en": "Sum up the directions in your own words", "es": "Resume el camino con tus palabras", "fr": "Résume le chemin avec tes mots", "it": "Riassumi la strada con parole tue", "pt": "Resume o caminho por palavras tuas"}, "hint": "Donc je prends à gauche, puis …"}]', 'Tu es une passante serviable dans une ville française. L’apprenant cherche la gare. Explique le chemin en deux ou trois étapes simples, puis vérifie qu’il a compris.', 2),
  ('directions', 'en', 'Asking for directions', 'travel', 'A1', 'B1', 5, 'scenarios/directions.webp', '{"de": "Weg finden", "en": "Finding your way", "es": "Orientarse", "fr": "Trouver son chemin", "it": "Orientarsi", "pt": "Encontrar o caminho"}', '{"de": "Du bist neu in der Stadt und suchst den Bahnhof. Sprich eine Passantin an und lass dir den Weg erklären.", "en": "You are new in town and looking for the station. Stop a passer-by and get directions.", "es": "Eres nuevo en la ciudad y buscas la estación. Para a una transeúnte y pide indicaciones.", "fr": "Tu es nouveau en ville et tu cherches la gare. Aborde une passante et fais-toi expliquer le chemin.", "it": "Sei nuovo in città e cerchi la stazione. Ferma una passante e fatti spiegare la strada.", "pt": "És novo na cidade e procuras a estação. Aborda uma transeunte e pede indicações."}', '[{"id": "ask", "level": "A1", "text": {"de": "Frag höflich nach dem Weg zum Bahnhof", "en": "Politely ask the way to the station", "es": "Pregunta amablemente cómo llegar a la estación", "fr": "Demande poliment le chemin de la gare", "it": "Chiedi gentilmente la strada per la stazione", "pt": "Pergunta com educação o caminho para a estação"}, "hint": "Excuse me, where is the station?"}, {"id": "repeat", "level": "A2", "text": {"de": "Bitte darum, es langsamer zu wiederholen", "en": "Ask them to repeat more slowly", "es": "Pide que lo repita más despacio", "fr": "Demande de répéter plus lentement", "it": "Chiedi di ripetere più lentamente", "pt": "Pede para repetir mais devagar"}, "hint": "Could you say that more slowly?"}, {"id": "confirm", "level": "B1", "text": {"de": "Fasse den Weg mit eigenen Worten zusammen", "en": "Sum up the directions in your own words", "es": "Resume el camino con tus palabras", "fr": "Résume le chemin avec tes mots", "it": "Riassumi la strada con parole tue", "pt": "Resume o caminho por palavras tuas"}, "hint": "So I turn left, then …"}]', 'You are a helpful passer-by in an English town. The learner is looking for the station. Give the way in two or three simple steps, then check they understood.', 2),
  ('directions', 'es', 'Preguntar el camino', 'travel', 'A1', 'B1', 5, 'scenarios/directions.webp', '{"de": "Weg finden", "en": "Finding your way", "es": "Orientarse", "fr": "Trouver son chemin", "it": "Orientarsi", "pt": "Encontrar o caminho"}', '{"de": "Du bist neu in der Stadt und suchst den Bahnhof. Sprich eine Passantin an und lass dir den Weg erklären.", "en": "You are new in town and looking for the station. Stop a passer-by and get directions.", "es": "Eres nuevo en la ciudad y buscas la estación. Para a una transeúnte y pide indicaciones.", "fr": "Tu es nouveau en ville et tu cherches la gare. Aborde une passante et fais-toi expliquer le chemin.", "it": "Sei nuovo in città e cerchi la stazione. Ferma una passante e fatti spiegare la strada.", "pt": "És novo na cidade e procuras a estação. Aborda uma transeunte e pede indicações."}', '[{"id": "ask", "level": "A1", "text": {"de": "Frag höflich nach dem Weg zum Bahnhof", "en": "Politely ask the way to the station", "es": "Pregunta amablemente cómo llegar a la estación", "fr": "Demande poliment le chemin de la gare", "it": "Chiedi gentilmente la strada per la stazione", "pt": "Pergunta com educação o caminho para a estação"}, "hint": "Perdone, ¿dónde está la estación?"}, {"id": "repeat", "level": "A2", "text": {"de": "Bitte darum, es langsamer zu wiederholen", "en": "Ask them to repeat more slowly", "es": "Pide que lo repita más despacio", "fr": "Demande de répéter plus lentement", "it": "Chiedi di ripetere più lentamente", "pt": "Pede para repetir mais devagar"}, "hint": "¿Podría repetirlo más despacio?"}, {"id": "confirm", "level": "B1", "text": {"de": "Fasse den Weg mit eigenen Worten zusammen", "en": "Sum up the directions in your own words", "es": "Resume el camino con tus palabras", "fr": "Résume le chemin avec tes mots", "it": "Riassumi la strada con parole tue", "pt": "Resume o caminho por palavras tuas"}, "hint": "Entonces giro a la izquierda y luego …"}]', 'Eres una transeúnte amable en una ciudad española. El estudiante busca la estación. Explica el camino en dos o tres pasos sencillos y comprueba que lo ha entendido.', 2),
  ('restaurant', 'fr', 'Au restaurant', 'food', 'A1', 'B1', 7, 'scenarios/restaurant.webp', '{"de": "Abendessen", "en": "Dinner out", "es": "Cena fuera", "fr": "Dîner au restaurant", "it": "Cena fuori", "pt": "Jantar fora"}', '{"de": "Du sitzt in einem kleinen Restaurant. Bestell etwas zu essen und zu trinken und bitte am Ende um die Rechnung.", "en": "You are sitting in a small restaurant. Order something to eat and drink, and ask for the bill at the end.", "es": "Estás en un pequeño restaurante. Pide algo de comer y de beber y, al final, pide la cuenta.", "fr": "Tu es dans un petit restaurant. Commande à manger et à boire, puis demande l’addition.", "it": "Sei in un piccolo ristorante. Ordina da mangiare e da bere e alla fine chiedi il conto.", "pt": "Estás num pequeno restaurante. Pede algo para comer e beber e, no fim, pede a conta."}', '[{"id": "drink", "level": "A1", "text": {"de": "Bestell ein Getränk", "en": "Order a drink", "es": "Pide una bebida", "fr": "Commande une boisson", "it": "Ordina da bere", "pt": "Pede uma bebida"}, "hint": "Je voudrais un verre d’eau, s’il vous plaît."}, {"id": "dish", "level": "A2", "text": {"de": "Frag nach einer Empfehlung und bestell ein Gericht", "en": "Ask for a recommendation and order a dish", "es": "Pide una recomendación y un plato", "fr": "Demande une recommandation et commande un plat", "it": "Chiedi un consiglio e ordina un piatto", "pt": "Pede uma recomendação e um prato"}, "hint": "Qu’est-ce que vous me conseillez ?"}, {"id": "bill", "level": "A1", "text": {"de": "Bitte um die Rechnung", "en": "Ask for the bill", "es": "Pide la cuenta", "fr": "Demande l’addition", "it": "Chiedi il conto", "pt": "Pede a conta"}, "hint": "L’addition, s’il vous plaît."}]', 'Tu es serveur dans un petit restaurant français. Accueille l’apprenant, prends sa commande, propose une spécialité et apporte l’addition quand il la demande.', 3),
  ('restaurant', 'en', 'At the restaurant', 'food', 'A1', 'B1', 7, 'scenarios/restaurant.webp', '{"de": "Abendessen", "en": "Dinner out", "es": "Cena fuera", "fr": "Dîner au restaurant", "it": "Cena fuori", "pt": "Jantar fora"}', '{"de": "Du sitzt in einem kleinen Restaurant. Bestell etwas zu essen und zu trinken und bitte am Ende um die Rechnung.", "en": "You are sitting in a small restaurant. Order something to eat and drink, and ask for the bill at the end.", "es": "Estás en un pequeño restaurante. Pide algo de comer y de beber y, al final, pide la cuenta.", "fr": "Tu es dans un petit restaurant. Commande à manger et à boire, puis demande l’addition.", "it": "Sei in un piccolo ristorante. Ordina da mangiare e da bere e alla fine chiedi il conto.", "pt": "Estás num pequeno restaurante. Pede algo para comer e beber e, no fim, pede a conta."}', '[{"id": "drink", "level": "A1", "text": {"de": "Bestell ein Getränk", "en": "Order a drink", "es": "Pide una bebida", "fr": "Commande une boisson", "it": "Ordina da bere", "pt": "Pede uma bebida"}, "hint": "I’d like a glass of water, please."}, {"id": "dish", "level": "A2", "text": {"de": "Frag nach einer Empfehlung und bestell ein Gericht", "en": "Ask for a recommendation and order a dish", "es": "Pide una recomendación y un plato", "fr": "Demande une recommandation et commande un plat", "it": "Chiedi un consiglio e ordina un piatto", "pt": "Pede uma recomendação e um prato"}, "hint": "What do you recommend?"}, {"id": "bill", "level": "A1", "text": {"de": "Bitte um die Rechnung", "en": "Ask for the bill", "es": "Pide la cuenta", "fr": "Demande l’addition", "it": "Chiedi il conto", "pt": "Pede a conta"}, "hint": "Could I have the bill, please?"}]', 'You are a waiter in a small restaurant. Welcome the learner, take their order, suggest a special and bring the bill when asked.', 3),
  ('restaurant', 'es', 'En el restaurante', 'food', 'A1', 'B1', 7, 'scenarios/restaurant.webp', '{"de": "Abendessen", "en": "Dinner out", "es": "Cena fuera", "fr": "Dîner au restaurant", "it": "Cena fuori", "pt": "Jantar fora"}', '{"de": "Du sitzt in einem kleinen Restaurant. Bestell etwas zu essen und zu trinken und bitte am Ende um die Rechnung.", "en": "You are sitting in a small restaurant. Order something to eat and drink, and ask for the bill at the end.", "es": "Estás en un pequeño restaurante. Pide algo de comer y de beber y, al final, pide la cuenta.", "fr": "Tu es dans un petit restaurant. Commande à manger et à boire, puis demande l’addition.", "it": "Sei in un piccolo ristorante. Ordina da mangiare e da bere e alla fine chiedi il conto.", "pt": "Estás num pequeno restaurante. Pede algo para comer e beber e, no fim, pede a conta."}', '[{"id": "drink", "level": "A1", "text": {"de": "Bestell ein Getränk", "en": "Order a drink", "es": "Pide una bebida", "fr": "Commande une boisson", "it": "Ordina da bere", "pt": "Pede uma bebida"}, "hint": "Quería un vaso de agua, por favor."}, {"id": "dish", "level": "A2", "text": {"de": "Frag nach einer Empfehlung und bestell ein Gericht", "en": "Ask for a recommendation and order a dish", "es": "Pide una recomendación y un plato", "fr": "Demande une recommandation et commande un plat", "it": "Chiedi un consiglio e ordina un piatto", "pt": "Pede uma recomendação e um prato"}, "hint": "¿Qué me recomienda?"}, {"id": "bill", "level": "A1", "text": {"de": "Bitte um die Rechnung", "en": "Ask for the bill", "es": "Pide la cuenta", "fr": "Demande l’addition", "it": "Chiedi il conto", "pt": "Pede a conta"}, "hint": "La cuenta, por favor."}]', 'Eres camarero en un pequeño restaurante español. Recibe al estudiante, toma nota, recomienda un plato y trae la cuenta cuando la pida.', 3),
  ('hotel', 'fr', 'À la réception', 'travel', 'A2', 'B2', 6, 'scenarios/hotel.webp', '{"de": "Einchecken", "en": "Checking in", "es": "Registrarse", "fr": "Arriver à l’hôtel", "it": "Fare il check-in", "pt": "Fazer o check-in"}', '{"de": "Du kommst abends im Hotel an. Check ein, frag nach dem Frühstück und melde ein Problem mit dem Zimmer.", "en": "You arrive at the hotel in the evening. Check in, ask about breakfast and report a problem with the room.", "es": "Llegas al hotel por la noche. Regístrate, pregunta por el desayuno y comunica un problema con la habitación.", "fr": "Tu arrives à l’hôtel le soir. Fais ton check-in, renseigne-toi sur le petit-déjeuner et signale un problème dans la chambre.", "it": "Arrivi in hotel di sera. Fai il check-in, chiedi della colazione e segnala un problema in camera.", "pt": "Chegas ao hotel à noite. Faz o check-in, pergunta pelo pequeno-almoço e comunica um problema no quarto."}', '[{"id": "checkin", "level": "A2", "text": {"de": "Nenne deine Reservierung und check ein", "en": "Give your booking and check in", "es": "Indica tu reserva y regístrate", "fr": "Donne ta réservation et fais ton check-in", "it": "Indica la prenotazione e fai il check-in", "pt": "Indica a tua reserva e faz o check-in"}, "hint": "J’ai une réservation au nom de …"}, {"id": "breakfast", "level": "A2", "text": {"de": "Frag, wann und wo es Frühstück gibt", "en": "Ask when and where breakfast is served", "es": "Pregunta cuándo y dónde es el desayuno", "fr": "Demande où et à quelle heure est le petit-déjeuner", "it": "Chiedi a che ora e dove c’è la colazione", "pt": "Pergunta a que horas e onde é o pequeno-almoço"}, "hint": "Le petit-déjeuner est à quelle heure ?"}, {"id": "problem", "level": "B1", "text": {"de": "Beschwer dich höflich über ein Problem im Zimmer", "en": "Politely complain about a problem in the room", "es": "Quéjate con educación de un problema en la habitación", "fr": "Signale poliment un problème dans la chambre", "it": "Lamentati gentilmente di un problema in camera", "pt": "Queixa-te com educação de um problema no quarto"}, "hint": "Excusez-moi, la douche ne fonctionne pas."}]', 'Tu es réceptionniste dans un hôtel en France. L’apprenant arrive le soir. Fais le check-in, réponds à ses questions et propose une solution s’il signale un problème.', 4),
  ('hotel', 'en', 'At the reception', 'travel', 'A2', 'B2', 6, 'scenarios/hotel.webp', '{"de": "Einchecken", "en": "Checking in", "es": "Registrarse", "fr": "Arriver à l’hôtel", "it": "Fare il check-in", "pt": "Fazer o check-in"}', '{"de": "Du kommst abends im Hotel an. Check ein, frag nach dem Frühstück und melde ein Problem mit dem Zimmer.", "en": "You arrive at the hotel in the evening. Check in, ask about breakfast and report a problem with the room.", "es": "Llegas al hotel por la noche. Regístrate, pregunta por el desayuno y comunica un problema con la habitación.", "fr": "Tu arrives à l’hôtel le soir. Fais ton check-in, renseigne-toi sur le petit-déjeuner et signale un problème dans la chambre.", "it": "Arrivi in hotel di sera. Fai il check-in, chiedi della colazione e segnala un problema in camera.", "pt": "Chegas ao hotel à noite. Faz o check-in, pergunta pelo pequeno-almoço e comunica um problema no quarto."}', '[{"id": "checkin", "level": "A2", "text": {"de": "Nenne deine Reservierung und check ein", "en": "Give your booking and check in", "es": "Indica tu reserva y regístrate", "fr": "Donne ta réservation et fais ton check-in", "it": "Indica la prenotazione e fai il check-in", "pt": "Indica a tua reserva e faz o check-in"}, "hint": "I have a booking under the name …"}, {"id": "breakfast", "level": "A2", "text": {"de": "Frag, wann und wo es Frühstück gibt", "en": "Ask when and where breakfast is served", "es": "Pregunta cuándo y dónde es el desayuno", "fr": "Demande où et à quelle heure est le petit-déjeuner", "it": "Chiedi a che ora e dove c’è la colazione", "pt": "Pergunta a que horas e onde é o pequeno-almoço"}, "hint": "What time is breakfast?"}, {"id": "problem", "level": "B1", "text": {"de": "Beschwer dich höflich über ein Problem im Zimmer", "en": "Politely complain about a problem in the room", "es": "Quéjate con educación de un problema en la habitación", "fr": "Signale poliment un problème dans la chambre", "it": "Lamentati gentilmente di un problema in camera", "pt": "Queixa-te com educação de um problema no quarto"}, "hint": "Sorry, the shower isn’t working."}]', 'You are the receptionist at a hotel. The learner arrives in the evening. Check them in, answer their questions and offer a solution if they report a problem.', 4),
  ('hotel', 'es', 'En la recepción', 'travel', 'A2', 'B2', 6, 'scenarios/hotel.webp', '{"de": "Einchecken", "en": "Checking in", "es": "Registrarse", "fr": "Arriver à l’hôtel", "it": "Fare il check-in", "pt": "Fazer o check-in"}', '{"de": "Du kommst abends im Hotel an. Check ein, frag nach dem Frühstück und melde ein Problem mit dem Zimmer.", "en": "You arrive at the hotel in the evening. Check in, ask about breakfast and report a problem with the room.", "es": "Llegas al hotel por la noche. Regístrate, pregunta por el desayuno y comunica un problema con la habitación.", "fr": "Tu arrives à l’hôtel le soir. Fais ton check-in, renseigne-toi sur le petit-déjeuner et signale un problème dans la chambre.", "it": "Arrivi in hotel di sera. Fai il check-in, chiedi della colazione e segnala un problema in camera.", "pt": "Chegas ao hotel à noite. Faz o check-in, pergunta pelo pequeno-almoço e comunica um problema no quarto."}', '[{"id": "checkin", "level": "A2", "text": {"de": "Nenne deine Reservierung und check ein", "en": "Give your booking and check in", "es": "Indica tu reserva y regístrate", "fr": "Donne ta réservation et fais ton check-in", "it": "Indica la prenotazione e fai il check-in", "pt": "Indica a tua reserva e faz o check-in"}, "hint": "Tengo una reserva a nombre de …"}, {"id": "breakfast", "level": "A2", "text": {"de": "Frag, wann und wo es Frühstück gibt", "en": "Ask when and where breakfast is served", "es": "Pregunta cuándo y dónde es el desayuno", "fr": "Demande où et à quelle heure est le petit-déjeuner", "it": "Chiedi a che ora e dove c’è la colazione", "pt": "Pergunta a que horas e onde é o pequeno-almoço"}, "hint": "¿A qué hora es el desayuno?"}, {"id": "problem", "level": "B1", "text": {"de": "Beschwer dich höflich über ein Problem im Zimmer", "en": "Politely complain about a problem in the room", "es": "Quéjate con educación de un problema en la habitación", "fr": "Signale poliment un problème dans la chambre", "it": "Lamentati gentilmente di un problema in camera", "pt": "Queixa-te com educação de um problema no quarto"}, "hint": "Disculpe, la ducha no funciona."}]', 'Eres recepcionista de un hotel en España. El estudiante llega por la noche. Haz el check-in, responde a sus preguntas y ofrece una solución si comunica un problema.', 4)
